package com.example.demo;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
record NouveauLivre(String titre) {}
record LivrePublic(long id, String titre) {}
@RestController
class AtelierController {
  @PostMapping("/livres") @ResponseStatus(HttpStatus.CREATED)
  LivrePublic creer(@RequestBody NouveauLivre entree) {
    if (entree == null || entree.titre() == null || entree.titre().isBlank())
      throw new IllegalArgumentException("titre requis");
    return new LivrePublic(1, entree.titre().trim());
  }
}

package com.example.demo;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
@RestControllerAdvice
class Erreurs {
  @ExceptionHandler(IllegalArgumentException.class) @ResponseStatus(HttpStatus.BAD_REQUEST)
  String invalide(IllegalArgumentException e) { return e.getMessage(); }
}
